const triggerInput =
  $('When Executed by Another Workflow')
    .first()
    .json;

const incomeResponse =
  $('Get Income Statement')
    .first()
    .json;

const earningsResponse =
  $('Get Earnings')
    .first()
    .json;

const cashFlowResponse =
  $('Get Cash Flow')
    .first()
    .json;

const overviewResponse =
  $('Get Company Overview')
    .first()
    .json;

const input = {
  ticker:
    triggerInput.ticker ||
    overviewResponse.Symbol,

  income:
    incomeResponse,

  earnings:
    earningsResponse,

  cashflow:
    cashFlowResponse,

  overview:
    overviewResponse
};

const ticker = String(
  input.ticker || ''
)
  .trim()
  .toUpperCase();

if (!ticker) {
  throw new Error(
    'A ticker symbol is required.'
  );
}

function checkApiResponse(response, label) {
  if (!response) {
    throw new Error(
      label + ' response is missing.'
    );
  }

  const message =
    response['Error Message'] ||
    response.Note ||
    response.Information;

  if (message) {
    throw new Error(
      label + ': ' + message
    );
  }
}

checkApiResponse(
  input.income,
  'Income statement API'
);

checkApiResponse(
  input.earnings,
  'Earnings API'
);

checkApiResponse(
  input.cashflow,
  'Cash-flow API'
);

checkApiResponse(
  input.overview,
  'Company overview API'
);

function asNumber(value) {
  if (
    value === undefined ||
    value === null
  ) {
    return null;
  }

  const text = String(value)
    .split(',')
    .join('')
    .trim();

  if (
    text === '' ||
    text === 'None' ||
    text === 'null' ||
    text === '-'
  ) {
    return null;
  }

  const parsed = Number(text);

  return Number.isFinite(parsed)
    ? parsed
    : null;
}

function round(value, decimals = 2) {
  if (value === null) {
    return null;
  }

  const factor =
    Math.pow(10, decimals);

  return Math.round(
    (value + Number.EPSILON) *
    factor
  ) / factor;
}

function growthPercent(
  current,
  previous
) {
  if (
    current === null ||
    previous === null ||
    previous === 0
  ) {
    return null;
  }

  return round(
    (
      current /
      previous -
      1
    ) * 100,
    2
  );
}

function sumAvailable(values) {
  const valid = values.filter(
    value => value !== null
  );

  if (valid.length === 0) {
    return null;
  }

  return valid.reduce(
    (total, value) =>
      total + value,
    0
  );
}

function averageAvailable(values) {
  const valid = values.filter(
    value => value !== null
  );

  if (valid.length === 0) {
    return null;
  }

  return (
    valid.reduce(
      (total, value) =>
        total + value,
      0
    ) /
    valid.length
  );
}

const incomeRows = [
  ...(input.income.quarterlyReports || [])
].sort(
  (first, second) =>
    Date.parse(
      second.fiscalDateEnding
    ) -
    Date.parse(
      first.fiscalDateEnding
    )
);

const earningsRows =
  input.earnings.quarterlyEarnings ||
  [];

const cashFlowRows =
  input.cashflow.quarterlyReports ||
  [];

if (incomeRows.length === 0) {
  throw new Error(
    'No quarterly income statements were returned.'
  );
}

const earningsByDate = new Map(
  earningsRows.map(row => [
    row.fiscalDateEnding,
    row
  ])
);

const cashFlowByDate = new Map(
  cashFlowRows.map(row => [
    row.fiscalDateEnding,
    row
  ])
);

const quarters = incomeRows
  .slice(0, 8)
  .map((incomeRow, index) => {
    const fiscalDate =
      incomeRow.fiscalDateEnding;

    const priorYearIncome =
      incomeRows[index + 4] ||
      null;

    const priorYearDate =
      priorYearIncome
        ? priorYearIncome
            .fiscalDateEnding
        : null;

    const earningsRow =
      earningsByDate.get(
        fiscalDate
      ) || {};

    const priorEarningsRow =
      priorYearDate
        ? earningsByDate.get(
            priorYearDate
          ) || {}
        : {};

    const cashFlowRow =
      cashFlowByDate.get(
        fiscalDate
      ) || {};

    const revenue =
      asNumber(
        incomeRow.totalRevenue
      );

    const priorRevenue =
      asNumber(
        priorYearIncome
          ? priorYearIncome
              .totalRevenue
          : null
      );

    const reportedEps =
      asNumber(
        earningsRow.reportedEPS
      );

    const priorReportedEps =
      asNumber(
        priorEarningsRow.reportedEPS
      );

    const operatingCashFlow =
      asNumber(
        cashFlowRow
          .operatingCashflow
      );

    const capitalExpendituresRaw =
      asNumber(
        cashFlowRow
          .capitalExpenditures
      );

    const capitalExpenditures =
      capitalExpendituresRaw === null
        ? null
        : Math.abs(
            capitalExpendituresRaw
          );

    const freeCashFlow =
      operatingCashFlow === null
        ? null
        : operatingCashFlow -
          (
            capitalExpenditures ||
            0
          );

    const buybackRaw =
      asNumber(
        cashFlowRow
          .paymentsForRepurchaseOfCommonStock
      );

    const buybackCash =
      buybackRaw === null
        ? null
        : Math.abs(buybackRaw);

    const operatingIncome =
      asNumber(
        incomeRow.operatingIncome
      );

    const netIncome =
      asNumber(
        incomeRow.netIncome
      );

    return {
      fiscal_date:
        fiscalDate,

      revenue:
        revenue,

      revenue_yoy_percent:
        growthPercent(
          revenue,
          priorRevenue
        ),

      reported_eps:
        reportedEps,

      eps_yoy_percent:
        growthPercent(
          reportedEps,
          priorReportedEps
        ),

      operating_income:
        operatingIncome,

      operating_margin_percent:
        revenue &&
        operatingIncome !== null
          ? round(
              operatingIncome /
              revenue *
              100,
              2
            )
          : null,

      net_income:
        netIncome,

      net_margin_percent:
        revenue &&
        netIncome !== null
          ? round(
              netIncome /
              revenue *
              100,
              2
            )
          : null,

      operating_cash_flow:
        operatingCashFlow,

      capital_expenditures:
        capitalExpenditures,

      free_cash_flow:
        freeCashFlow,

      buyback_cash:
        buybackCash
    };
  });

const latestFour =
  quarters.slice(0, 4);

const availableRevenueGrowth =
  quarters
    .map(
      quarter =>
        quarter
          .revenue_yoy_percent
    )
    .filter(
      value => value !== null
    );

const availableEpsGrowth =
  quarters
    .map(
      quarter =>
        quarter
          .eps_yoy_percent
    )
    .filter(
      value => value !== null
    );

const positiveRevenueGrowthQuarters =
  availableRevenueGrowth.filter(
    value => value > 0
  ).length;

const positiveEpsGrowthQuarters =
  availableEpsGrowth.filter(
    value => value > 0
  ).length;

const positiveFcfQuarters =
  quarters.filter(
    quarter =>
      quarter.free_cash_flow !==
        null &&
      quarter.free_cash_flow > 0
  ).length;

const overview =
  input.overview || {};

return [
  {
    json: {
      answer_type:
        'company_financial_metrics',

      ticker,

      company_name:
        overview.Name || null,

      sector:
        overview.Sector || null,

      industry:
        overview.Industry || null,

      data_as_of:
        overview.LatestQuarter ||
        (
          quarters[0]
            ? quarters[0]
                .fiscal_date
            : null
        ),

      valuation: {
        market_cap:
          asNumber(
            overview
              .MarketCapitalization
          ),

        pe_ratio:
          asNumber(
            overview.PERatio
          ),

        forward_pe:
          asNumber(
            overview.ForwardPE
          ),

        price_to_book:
          asNumber(
            overview.PriceToBookRatio
          ),

        dividend_yield_percent:
          overview.DividendYield
            ? round(
                asNumber(
                  overview
                    .DividendYield
                ) * 100,
                2
              )
            : null
      },

      trailing_four_quarters: {
        revenue:
          sumAvailable(
            latestFour.map(
              quarter =>
                quarter.revenue
            )
          ),

        net_income:
          sumAvailable(
            latestFour.map(
              quarter =>
                quarter.net_income
            )
          ),

        operating_cash_flow:
          sumAvailable(
            latestFour.map(
              quarter =>
                quarter
                  .operating_cash_flow
            )
          ),

        free_cash_flow:
          sumAvailable(
            latestFour.map(
              quarter =>
                quarter
                  .free_cash_flow
            )
          ),

        buyback_cash:
          sumAvailable(
            latestFour.map(
              quarter =>
                quarter
                  .buyback_cash
            )
          )
      },

      research_signals: {
        average_revenue_yoy_percent:
          round(
            averageAvailable(
              availableRevenueGrowth
            ),
            2
          ),

        positive_revenue_growth_quarters:
          positiveRevenueGrowthQuarters,

        revenue_growth_quarters_available:
          availableRevenueGrowth.length,

        average_eps_yoy_percent:
          round(
            averageAvailable(
              availableEpsGrowth
            ),
            2
          ),

        positive_eps_growth_quarters:
          positiveEpsGrowthQuarters,

        eps_growth_quarters_available:
          availableEpsGrowth.length,

        positive_free_cash_flow_quarters:
          positiveFcfQuarters,

        total_quarters_returned:
          quarters.length
      },

      quarters,

      source:
        'Alpha Vantage',

      limitations: [
        'Financial data should be checked against the original company filing.',
        'Valuation information may not be real-time.',
        'Historical growth does not guarantee future performance.',
        'Management outlook and risks require SEC filing retrieval.'
      ]
    }
  }
];

const input = $input.first().json;

const ticker = String(
  input.ticker || ''
)
  .trim()
  .toUpperCase();

if (ticker !== 'AAPL') {
  return [
    {
      json: {
        answer_type:
          'company_financial_metrics',

        ticker,

        supported:
          false,

        data_mode:
          'static_official_snapshot',

        message:
          'The current static demo snapshot supports AAPL only.',

        limitations: [
          'Add another company snapshot or restore the live financial-data API to research this ticker.'
        ]
      }
    }
  ];
}

const quarters = [
  {
    fiscal_quarter: '2026 Q3',
    period_end: '2026-06-27',
    revenue_billions: 109.4,
    revenue_yoy_percent: 16,
    reported_eps: 2.02,
    eps_yoy_percent: 29,
    eps_comparison_basis: 'reported'
  },
  {
    fiscal_quarter: '2026 Q2',
    period_end: '2026-03-28',
    revenue_billions: 111.2,
    revenue_yoy_percent: 17,
    reported_eps: 2.01,
    eps_yoy_percent: 22,
    eps_comparison_basis: 'reported'
  },
  {
    fiscal_quarter: '2026 Q1',
    period_end: '2025-12-27',
    revenue_billions: 143.756,
    revenue_yoy_percent: 16,
    reported_eps: 2.84,
    eps_yoy_percent: 19,
    eps_comparison_basis: 'reported'
  },
  {
    fiscal_quarter: '2025 Q4',
    period_end: '2025-09-27',
    revenue_billions: 102.5,
    revenue_yoy_percent: 8,
    reported_eps: 1.85,
    eps_yoy_percent: 13,
    eps_comparison_basis:
      'adjusted comparison because the prior-year quarter contained a one-time tax charge'
  },
  {
    fiscal_quarter: '2025 Q3',
    period_end: '2025-06-28',
    revenue_billions: 94.0,
    revenue_yoy_percent: 10,
    reported_eps: 1.57,
    eps_yoy_percent: 12,
    eps_comparison_basis: 'reported'
  },
  {
    fiscal_quarter: '2025 Q2',
    period_end: '2025-03-29',
    revenue_billions: 95.4,
    revenue_yoy_percent: 5,
    reported_eps: 1.65,
    eps_yoy_percent: 8,
    eps_comparison_basis: 'reported'
  },
  {
    fiscal_quarter: '2025 Q1',
    period_end: '2024-12-28',
    revenue_billions: 124.3,
    revenue_yoy_percent: 4,
    reported_eps: 2.40,
    eps_yoy_percent: 10,
    eps_comparison_basis: 'reported'
  },
  {
    fiscal_quarter: '2024 Q4',
    period_end: '2024-09-28',
    revenue_billions: 94.9,
    revenue_yoy_percent: 6,
    reported_eps: 0.97,
    adjusted_eps: 1.64,
    eps_yoy_percent: 12,
    eps_comparison_basis:
      'adjusted because reported EPS included a one-time tax charge'
  }
];

function average(values) {
  if (values.length === 0) {
    return null;
  }

  return values.reduce(
    (total, value) => total + value,
    0
  ) / values.length;
}

function round(value, decimals = 2) {
  const factor =
    Math.pow(10, decimals);

  return Math.round(
    (value + Number.EPSILON) *
    factor
  ) / factor;
}

const latestFour =
  quarters.slice(0, 4);

const trailingRevenue =
  latestFour.reduce(
    (total, quarter) =>
      total +
      quarter.revenue_billions,
    0
  );

const averageRevenueGrowth =
  average(
    quarters.map(
      quarter =>
        quarter.revenue_yoy_percent
    )
  );

const averageEpsGrowth =
  average(
    quarters.map(
      quarter =>
        quarter.eps_yoy_percent
    )
  );

return [
  {
    json: {
      answer_type:
        'company_financial_metrics',

      supported:
        true,

      ticker:
        'AAPL',

      company_name:
        'Apple Inc.',

      sector:
        'Technology',

      industry:
        'Consumer Electronics',

      currency:
        'USD',

      monetary_unit:
        'billions unless otherwise stated',

      data_mode:
        'static_official_snapshot',

      data_as_of:
        '2026-06-27',

      data_notice:
        'This is a fixed demonstration snapshot based on official Apple releases and SEC filings. It is not live market data.',

      research_signals: {
        average_revenue_yoy_percent:
          round(
            averageRevenueGrowth,
            2
          ),

        positive_revenue_growth_quarters:
          quarters.filter(
            quarter =>
              quarter
                .revenue_yoy_percent >
              0
          ).length,

        average_eps_yoy_percent:
          round(
            averageEpsGrowth,
            2
          ),

        positive_eps_growth_quarters:
          quarters.filter(
            quarter =>
              quarter
                .eps_yoy_percent >
              0
          ).length,

        total_quarters:
          quarters.length
      },

      trailing_four_quarters: {
        revenue_billions:
          round(
            trailingRevenue,
            3
          ),

        operating_cash_flow_billions:
          146.724,

        capital_expenditures_billions:
          10.041,

        free_cash_flow_billions:
          136.683,

        actual_share_repurchases_billions:
          82.226,

        cash_flow_basis:
          'Derived from Apple fiscal 2025 annual and fiscal 2026 nine-month SEC cash-flow statements.'
      },

      valuation: {
        status:
          'not_available_in_static_snapshot',

        explanation:
          'Current valuation requires a live share price and current market-cap data. The application should not fabricate it.'
      },

      quarters,

      sources: [
        {
          source_type:
            'Apple quarterly earnings releases',

          use:
            'Eight-quarter revenue and EPS history'
        },
        {
          source_type:
            'Apple fiscal 2025 Form 10-K',

          use:
            'Annual operating cash flow, capital expenditures and share repurchases'
        },
        {
          source_type:
            'Apple fiscal 2026 Q3 Form 10-Q',

          use:
            'Nine-month operating cash flow, capital expenditures and share repurchases'
        }
      ],

      limitations: [
        'This is a fixed snapshot rather than a live API response.',
        'Current valuation is intentionally unavailable.',
        'Quarterly free cash flow is not included; the fallback supplies a trailing-four-quarter aggregate.',
        'Historical growth does not guarantee future performance.',
        'Qualitative risks and management discussion must come from sec_filing_search.'
      ]
    }
  }
];
